const q = {"abstract":[{"id":"abstract-symb-001","f":"single_best","skill":"suite-logique","difficulty":1,"p":"Quel élément complète logiquement cette série ?","s":{"type":"shapes","text":"○  ●  □  ■  △  ?"},"o":["▲","●","◆","△"],"a":0,"e":"Chaque forme apparaît deux fois de suite, d'abord vide puis pleine : cercle, carré, puis triangle. Après △ vient donc ▲.","x":["Correct : le triangle vide est suivi du triangle plein.","Le cercle a déjà été traité au début de la série.","Le losange n'appartient pas à la séquence cercle, carré, triangle.","Répète la figure vide au lieu de passer à sa version pleine."]},{"id":"abstract-arrow-002","f":"single_best","skill":"rotation","difficulty":1,"p":"Quelle paire de flèches complète la suite ?","s":{"type":"shapes","text":"↑ →     ↓ ←     ↑ →     ?"},"o":["↓ ←","→ ↓","← ↑","↑ →"],"a":0,"e":"Chaque paire est la précédente tournée de 180° : ↑ → devient ↓ ←, puis de nouveau ↑ →. La quatrième paire est donc ↓ ←.","x":["Correct : rotation de 180° de la paire ↑ →.","Rotation de 90° seulement.","Rotation de 270° (ou 90° anti-horaire).","Répète la paire sans rotation."]},{"id":"abstract-latin-003","f":"single_best","skill":"matrice","difficulty":1,"p":"Quelle figure remplace le point d'interrogation dans la matrice ?","s":{"type":"shapes","text":"●  ■  ▲\n■  ▲  ●\n▲  ●  ?"},"o":["■","●","▲","□"],"a":0,"e":"Chaque ligne et chaque colonne contient une seule fois le disque, le carré et le triangle, tous pleins. La dernière ligne et la dernière colonne manquent toutes deux du carré plein ■.","x":["Correct : seul figure absente de la ligne et de la colonne.","Le disque figure déjà dans la dernière ligne.","Le triangle figure déjà dans la dernière ligne.","Bonne forme, mais toutes les figures de la matrice sont pleines."]},{"id":"abstract-grid-004","f":"single_best","skill":"matrice","difficulty":2,"p":"Quelle case complète la matrice ?","s":{"type":"shapes","text":"●      ○○      ●●●\n■      □□      ■■■\n▲      △△      ?"},"o":["▲▲▲","△△△","▲▲","■■■"],"a":0,"e":"Trois règles : la forme est fixe sur chaque ligne ; le nombre de figures vaut 1, 2 puis 3 selon la colonne ; la colonne du milieu est vide, les autres pleines. Ligne 3, colonne 3 : trois triangles pleins.","x":["Correct : forme, nombre et remplissage respectés.","Le remplissage vide ne vaut que pour la colonne du milieu.","Le nombre doit être 3 dans la dernière colonne.","La forme doit rester le triangle sur la troisième ligne."]},{"id":"abstract-dots-005","f":"single_best","skill":"suite-logique","difficulty":1,"p":"Quel groupe de points complète la progression ?","s":{"type":"shapes","text":"●     ●●     ●●●     ?"},"o":["●●","●●●●","○○○○","●●●●●"],"a":1,"e":"Le nombre de disques pleins augmente d'une unité à chaque étape : 1, 2, 3, puis 4.","x":["Revient en arrière au lieu de progresser.","Correct : quatre disques pleins.","Bon nombre, mais le remplissage change sans raison.","Augmente de deux unités au lieu d'une."]},{"id":"abstract-rot-006","f":"single_best","skill":"rotation","difficulty":2,"p":"Quelle figure vient ensuite dans la série ?","s":{"type":"shapes","text":"◰  →  ◳  →  ◲  →  ?"},"o":["◱","◰","◳","◲"],"a":0,"e":"Le quadrant marqué tourne d'un quart de tour dans le sens horaire : haut-gauche, haut-droite, bas-droite, puis bas-gauche (◱).","x":["Correct : quadrant bas-gauche après bas-droite.","Revient au point de départ, une étape trop tôt.","Rotation dans le sens inverse.","Répète la dernière figure."]},{"id":"abstract-interleave-007","f":"single_best","skill":"suite-logique","difficulty":2,"p":"Quel élément complète la série ?","s":{"type":"shapes","text":"●    ▲    ●●    ▲▲    ●●●    ?"},"o":["▲▲▲","●●●●","▲▲","▲▲▲▲"],"a":0,"e":"Deux suites alternent : les disques (1, 2, 3) et les triangles (1, 2, …). Le sixième terme appartient à la suite des triangles, qui passe à 3.","x":["Correct : troisième terme de la suite des triangles.","Prolonge la suite des disques au mauvais rang.","Répète le terme précédent de la suite des triangles.","Saute une étape de la progression."]},{"id":"abstract-flip-008","f":"single_best","skill":"transformation","difficulty":2,"p":"La même transformation s'applique à chaque paire. Quelle figure remplace le point d'interrogation ?","s":{"type":"shapes","text":"▲  →  ▽\n◀  →  ▷\n▼  →  ?"},"o":["△","▽","▲","◁"],"a":0,"e":"Les deux exemples montrent la même transformation : un demi-tour (180°) et l'inversion du remplissage. Seul le demi-tour explique à la fois ▲ → ▽ et ◀ → ▷ (une symétrie selon un seul axe ne marche que pour l'un des deux). ▼ tourné de 180° donne ▲, puis vide : △.","x":["Correct : demi-tour puis remplissage inversé.","Remplissage inversé, mais sans demi-tour.","Demi-tour, mais remplissage conservé.","Mauvaise orientation : la figure ne pointe ni vers le haut ni vers le bas."]},{"id":"abstract-mirror-009","f":"single_best","skill":"transformation","difficulty":3,"p":"Appliquez la même règle à la seconde ligne. Quel résultat obtient-on ?","s":{"type":"shapes","text":"●  ■  ▲   →   △  □  ○\n◆  ○  ■   →   ?"},"o":["□  ●  ◇","■  ○  ◆","◇  ●  □","□  ○  ◇"],"a":0,"e":"Deux règles combinées : l'ordre des figures est inversé, et chaque remplissage est inversé. ◆ ○ ■ inversé donne ■ ○ ◆, puis le remplissage inversé donne □ ● ◇.","x":["Correct : ordre inversé et remplissage inversé.","Ordre inversé, mais remplissage conservé.","Remplissage inversé, mais ordre conservé.","Le disque n'a pas été inversé."]},{"id":"abstract-gap-010","f":"single_best","skill":"suite-logique","difficulty":2,"p":"Quel élément complète la série ?","s":{"type":"shapes","text":"●  ■  ●  ■  ■  ●  ■  ■  ■  ?"},"o":["●","■","▲","○"],"a":0,"e":"Entre deux disques, le nombre de carrés augmente : 1, 2, puis 3. Après le troisième carré du groupe de trois vient donc un disque.","x":["Correct : le groupe de trois carrés est complet.","Un quatrième carré dépasserait le groupe de trois.","Le triangle n'apparaît pas dans la série.","Le disque est plein dans toute la série."]},{"id":"abstract-matrix-011","f":"single_best","skill":"matrice","difficulty":2,"p":"Quelle case complète logiquement la troisième ligne de cette matrice ?","s":{"type":"shapes","text":"●       ■       ▲\n■■      ▲▲      ●●\n▲▲▲     ●●●     ?"},"o":["■■■","▲▲▲","●●●","□□□"],"a":0,"e":"Deux règles combinées s'appliquent : d'une part, chaque ligne permute les trois formes de base (cercle, carré, triangle) ; d'autre part, le nombre de symboles augmente de 1 par ligne (1 en ligne 1, 2 en ligne 2, 3 en ligne 3). La case manquante doit donc contenir 3 carrés pleins (■■■).","x":["Correct : forme carrée requise pour compléter le triplet (triangle, disque, carré) avec 3 éléments pleins.","Le triangle figure déjà en première case de la troisième ligne.","Le disque figure déjà en deuxième case de la troisième ligne.","Forme correcte mais vide, alors que toutes les figures de la matrice sont pleines."]},{"id":"abstract-clock-012","f":"single_best","skill":"rotation","difficulty":2,"p":"Quelle flèche poursuit logiquement la rotation ?","s":{"type":"shapes","text":"↑  →  ↗  →  →  →  ↘  →  ?"},"o":["↓","↙","←","↑"],"a":0,"e":"La flèche effectue une rotation continue de 45° dans le sens horaire à chaque pas : nord (↑), nord-est (↗), est (→), sud-est (↘). L'étape suivante pointe donc plein sud (↓).","x":["Correct : rotation horaire de 45° après le point cardinal sud-est (↘).","Rotation de 90° au lieu de 45° après le sud-est.","Rotation de 135° sautant deux étapes d'orientation.","Retour erroné au point de départ de la séquence."]},{"id":"abstract-pair-013","f":"single_best","skill":"transformation","difficulty":2,"p":"La même règle s'applique à chaque couple. Quelle paire remplace le point d'interrogation ?","s":{"type":"shapes","text":"● ○   →   ○ ●\n■ □   →   □ ■\n▲ △   →   ?"},"o":["△ ▲","▲ △","△ △","▲ ▲"],"a":0,"e":"Chaque paire subit une permutation horizontale de ses deux composantes : le symbole plein à gauche passe à droite, et le symbole vide à droite passe à gauche. ▲ △ devient donc △ ▲.","x":["Correct : permutation de la figure pleine et de la figure vide.","Identique à la figure initiale sans appliquer la permutation.","Deux figures vides au lieu d'une permutation.","Deux figures pleines au lieu d'une permutation."]},{"id":"abstract-step-014","f":"single_best","skill":"suite-logique","difficulty":3,"p":"Quel groupe de symboles complète cette double progression ?","s":{"type":"shapes","text":"◆◆◆◆    ◇    ◆◆◆    ◇◇    ◆◆    ◇◇◇    ?"},"o":["◆","◇◇◇◇","◆◆","◇◇"],"a":0,"e":"Deux progressions entrelacées alternent : les termes impairs présentent des losanges pleins décroissants (4, 3, 2, puis 1), tandis que les termes pairs présentent des losanges vides croissants (1, 2, 3). Le 7e terme est impair et doit donc comporter un seul losange plein (◆).","x":["Correct : la suite des losanges pleins décroît (4, 3, 2, 1) au 7e terme.","Prolonge la suite des losanges vides qui n'intervient qu'au rang suivant.","Répète le terme précédent des losanges pleins sans décrémentation.","Régression injustifiée dans la suite des losanges vides."]},{"id":"abstract-diag-015","f":"single_best","skill":"matrice","difficulty":2,"p":"Quelle figure complète logiquement la matrice 2×2 ci-dessous ?","s":{"type":"shapes","text":"◀   ▶\n▲   ?"},"o":["▼","▲","◀","▶"],"a":0,"e":"La première ligne associe deux triangles horizontaux de directions opposées (◀ et ▶, soit un retournement à 180°). La seconde ligne applique la même relation d'opposition aux triangles verticaux : ▲ opposé donne ▼.","x":["Correct : symétrie axiale inversant l'orientation (gauche/droite en ligne 1, haut/bas en ligne 2).","Répétition sans inversion d'orientation.","Réintroduction d'une orientation horizontale sur une ligne verticale.","Orientation vers la droite sans rapport avec l'axe vertical de la seconde ligne."]}],"verbal":[{"id":"verbal-deduct-001","f":"single_best","skill":"inference","difficulty":1,"p":"Quelle conclusion est absolument certaine à partir des seuls éléments fournis ?","s":"Tous les dossiers urgents sont examinés le jour même. Le dossier L est urgent.","o":["Le dossier L est accepté.","Le dossier L est examiné le jour même.","Le dossier L est le premier examiné.","Tous les dossiers de la journée sont urgents."],"a":1,"e":"L'énoncé affirme expressément que tout dossier urgent fait l'objet d'un examen le jour même ; aucune conclusion sur la décision finale ou l'ordre exact n'est permise.","x":["L'examen ne préjuge en rien de la décision finale (acceptation ou rejet).","Correct : tout dossier urgent étant examiné le jour même, le dossier L l'est obligatoirement.","L'énoncé ne précise aucun ordre de passage parmi les dossiers examinés.","Généralise abusivement la propriété d'un sous-ensemble à l'ensemble des dossiers."]},{"id":"verbal-cond-002","f":"single_best","skill":"inference","difficulty":2,"p":"Quelle affirmation découle rigoureusement des conditions indiquées ?","s":"Le guichet ouvre à 8 h 30. Les rendez-vous avant 10 h sont réservés aux demandes déjà complètes. Nora a obtenu un rendez-vous à 9 h 15.","o":["La demande de Nora est déjà complète.","Nora sera reçue avant l'ouverture générale du guichet.","Nora sera reçue dès l'ouverture du guichet.","La demande de Nora sera automatiquement acceptée."],"a":0,"e":"Les créneaux avant 10 h sont réservés aux demandes déjà complètes ; un rendez-vous à 9 h 15 implique donc une demande complète. Le texte ne dit rien de l'heure exacte de passage, ni de la décision.","x":["Correct : les créneaux avant 10 h étant réservés aux dossiers complets, un créneau à 9 h 15 implique un dossier complet.","Le guichet ouvrant à 8 h 30, un rendez-vous à 9 h 15 a lieu après l'ouverture.","L'ouverture a lieu à 8 h 30, tandis que le rendez-vous de Nora est calé à 9 h 15.","L'obtention d'un rendez-vous ne préjuge aucunement de l'acceptation de la demande."]},{"id":"verbal-quant-003","f":"tfcs","skill":"vrai-faux-indetermine","difficulty":2,"p":"Affirmation : Malik travaille à distance.","s":"Certains analystes travaillent à distance. Malik est analyste.","o":["Vrai","Faux","On ne peut pas savoir"],"a":2,"e":"L'expression « certains » indique l'existence d'au moins un analyste à distance, sans préciser si Malik en fait partie.","x":["Généralise « certains » à tous les analystes.","Le texte n'exclut pas non plus que Malik travaille à distance.","Correct : « certains » ne permet pas de savoir si Malik en fait partie."]},{"id":"verbal-order-004","f":"single_best","skill":"application-consigne","difficulty":1,"p":"Quelle séquence respecte scrupuleusement la règle de classement ?","s":"Classer les dossiers par date croissante. À date identique, placer en premier le numéro le plus petit.","o":["12/04 n° 18, puis 11/04 n° 22","11/04 n° 22, puis 11/04 n° 19","11/04 n° 19, puis 11/04 n° 22","12/04 n° 12, puis 11/04 n° 10"],"a":2,"e":"À date identique (11/04), le numéro le plus faible (19) doit impérativement précéder le numéro plus élevé (22).","x":["Viole la préséance de date croissante (le 12/04 est placé avant le 11/04).","À date identique (11/04), le numéro le plus faible (19) doit impérativement précéder le 22.","Correct : date identique (11/04) et ordre croissant strict des numéros (19 avant 22).","Viole l'ordre chronologique croissant des dates."]},{"id":"verbal-neg-005","f":"single_best","skill":"inference","difficulty":2,"p":"Quelle conclusion n'est PAS justifiée par le passage ?","s":"Aucun rapport incomplet n'est transmis. Certains rapports du service B sont transmis.","o":["Certains rapports du service B sont complets.","Aucun rapport transmis n'est incomplet.","Tous les rapports du service B sont transmis.","Au moins un rapport du service B est transmis."],"a":2,"e":"Le passage mentionne que certains rapports sont transmis, ce qui interdit d'affirmer que tous les rapports du service le sont.","x":["Justifié : les rapports transmis étant nécessairement complets, ceux de B qui sont transmis sont complets.","Justifié : découle directement de la prémisse interdisant la transmission de rapports incomplets.","Correct : le fait que certains rapports soient transmis n'autorise pas à affirmer que tous le sont.","Justifié : l'emploi de « certains » implique l'existence d'au moins un élément."]},{"id":"verbal-syll-006","f":"single_best","skill":"inference","difficulty":2,"p":"Quelle déduction s'impose logiquement à partir des deux prémisses ?","s":"Tout arrêté ministériel fait l'objet d'une publication. Le document G ne fait l'objet d'aucune publication.","o":["Le document G n'est pas un arrêté ministériel.","Le document G est un projet de loi en cours.","Le document G sera publié ultérieurement.","Certains arrêtés ministériels ne sont pas publiés."],"a":0,"e":"Par contraposition logique : si tout arrêté est publié, un document non publié ne peut en aucun cas constituer un arrêté ministériel.","x":["Correct : par contraposition (si arrêté alors publié ; non publié donc pas un arrêté).","Spéculation sans fondement dans les prémisses fournies.","Supposition temporelle non étayée par le texte.","Contredit formellement la règle selon laquelle tout arrêté est publié."]},{"id":"verbal-rule-007","f":"single_best","skill":"application-consigne","difficulty":2,"p":"Quelle décision est conforme à la directive énoncée ?","s":"Toute demande de subvention supérieure à 50 000 euros requiert un avis préalable de la commission financière. Le projet Alpha sollicite 45 000 euros.","o":["Le projet Alpha ne requiert pas obligatoirement l'avis préalable de la commission financière au titre de cette règle.","Le projet Alpha doit impérativement obtenir l'accord unanime de la commission financière.","Le projet Alpha sera automatiquement rejeté pour insuffisance de montant.","Le projet Alpha est dispensé de tout contrôle administratif."],"a":0,"e":"Le seuil obligatoire est fixé strictement aux montants supérieurs à 50 000 euros ; 45 000 euros ne déclenchent pas cette obligation spécifique.","x":["Correct : le seuil d'exigence étant strictement supérieur à 50 000 euros, 45 000 euros n'activent pas cette obligation.","La règle n'évoque aucun accord unanime requis.","Confusion : la directive n'impose aucun seuil minimal pour solliciter une subvention.","Généralisation abusive : le projet n'est exempté que de cette formalité spécifique."]},{"id":"verbal-extrap-008","f":"single_best","skill":"inference","difficulty":3,"p":"Laquelle des propositions constitue une extrapolation non démontrée par le texte ?","s":"La dématérialisation des formulaires a réduit le délai moyen de traitement de 14 jours à 6 jours au premier semestre.","o":["Les usagers sont globalement plus satisfaits de la qualité de service.","Le délai moyen de traitement constaté s'est contracté de 8 jours.","Le délai moyen est passé sous la barre des dix jours au premier semestre.","Le traitement moyen était plus long avant le premier semestre concerné."],"a":0,"e":"Le texte renseigne un indicateur temporel précis (délai en jours), mais ne fournit aucune donnée sur le niveau de satisfaction des usagers.","x":["Correct : le texte n'apporte aucune donnée sur la satisfaction des usagers, seulement un indicateur de délai.","Parfaitement démontré par la différence arithmétique (14 - 6 = 8 jours).","Démontré par l'observation directe du chiffre de 6 jours.","Démontré par la comparaison avec la durée préalable de 14 jours."]},{"id":"verbal-equiv-009","f":"single_best","skill":"comprehension","difficulty":2,"p":"Quelle formulation exprime exactement le même sens logique ?","s":"Il est impossible d'accéder à la zone sécurisée sans badge d'identification actif.","o":["Avoir un badge actif est une condition indispensable pour accéder à la zone sécurisée.","Toute personne munie d'un badge actif a le droit d'entrer dans la zone sécurisée.","Les personnes sans badge peuvent être admises avec un accompagnateur.","Le badge actif garantit un accès permanent et sans restriction."],"a":0,"e":"L'absence de badge empêchant l'accès, la détention d'un badge actif constitue bien une condition nécessaire (indispensable) d'accès.","x":["Correct : l'impossibilité d'accéder sans badge fait de sa détention une condition nécessaire (indispensable).","Confond condition nécessaire et condition suffisante (le badge est requis, mais d'autres conditions peuvent s'appliquer).","Extrapole une exception d'accompagnement non stipulée dans la règle.","Le badge est requis, mais il ne confère aucun accès permanent ou sans restriction."]},{"id":"verbal-fact-010","f":"single_best","skill":"comprehension","difficulty":2,"p":"Quelle proposition relève d'un fait constatable et non d'une appréciation subjective ?","s":"Le nouveau logiciel de gestion des congés est remarquable, il enregistre 1 200 connexions quotidiennes et simplifie grandement la vie du personnel.","o":["Le logiciel enregistre 1 200 connexions quotidiennes.","Le nouveau logiciel est particulièrement remarquable.","La vie du personnel est grandement simplifiée.","Ce système est la meilleure solution disponible."],"a":0,"e":"Le comptage de 1 200 connexions est une mesure quantitative objectivement vérifiable, à la différence des appréciations qualitatives.","x":["Correct : le comptage de 1 200 connexions est une donnée objective et quantifiable.","Appréciation qualitative subjective.","Jugement de valeur subjectif quant au bien-être du personnel.","Jugement subjectif sans fondement factuel quantifié."]},{"id":"verbal-telework-011","f":"single_best","skill":"application-consigne","difficulty":2,"p":"Quelle décision est strictement conforme à la directive de service ?","s":"Toute demande de télétravail occasionnel doit être déposée au moins 5 jours ouvrés à l'avance auprès de la hiérarchie. Par exception, en cas d'intempéries majeures constatées par un avis officiel, le délai est réduit à 24 heures. L'agent Laurent dépose sa demande 3 jours ouvrés avant la date souhaitée, en l'absence de tout avis officiel d'intempéries.","o":["La demande de Laurent ne respecte pas le délai réglementaire exigé.","La demande de Laurent est automatiquement validée par défaut.","Laurent peut bénéficier de la dérogation réduite à 24 heures.","Le délai de 5 jours ouvrés ne s'applique qu'au télétravail régulier."],"a":0,"e":"La directive impose un préavis de 5 jours ouvrés pour le télétravail occasionnel. L'unique dérogation (24 heures) requiert un avis officiel d'intempéries. En l'absence d'un tel avis, la demande déposée à 3 jours ouvrés viole le délai réglementaire.","x":["Correct : en l'absence d'avis officiel d'intempéries, le délai obligatoire de 5 jours ouvrés s'applique.","Le texte ne mentionne aucun mécanisme d'accord tacite ou d'approbation automatique.","L'exception de 24 heures est expressément conditionnée à un avis officiel d'intempéries.","La directive précise explicitement qu'elle régit le télétravail occasionnel."]},{"id":"verbal-tfcs-012","f":"tfcs","skill":"vrai-faux-indetermine","difficulty":2,"p":"Affirmation : Tous les candidats retenus pour l'épreuve orale ont validé l'évaluation écrite.","s":"Seuls les candidats ayant validé l'évaluation écrite avec une note minimale de 12 sur 20 sont convoqués à l'épreuve orale. Vingt-cinq candidats participent actuellement à l'épreuve orale.","o":["Vrai","Faux","On ne peut pas savoir"],"a":0,"e":"L'emploi de la tournure restrictive « seuls les candidats ayant validé l'évaluation écrite... » établit que la validation écrite est une condition sine qua non. Tout candidat présent à l'oral l'a donc obligatoirement validée.","x":["Correct : la validation de l'évaluation écrite est une condition nécessaire stricte d'accès à l'oral.","Contredit formellement la règle d'admission énoncée dans le texte.","Le texte est affirmatif et sans ambiguïté sur cette condition exclusive (« seuls les candidats... »)."]},{"id":"verbal-synth-013","f":"single_best","skill":"synthese","difficulty":2,"p":"Quelle proposition résume le plus fidèlement le champ d'application de la note ?","s":"Le présent guide de gestion s'applique à l'ensemble des agents titulaires et stagiaires de l'administration centrale. Les collaborateurs externes et prestataires sont soumis exclusivement aux clauses de leur contrat spécifique, à l'exception des consignes de sécurité des bâtiments qui s'imposent à toute personne présente dans les locaux.","o":["Le guide régit titulaires et stagiaires, tandis que seules les consignes de sécurité s'imposent universellement.","Le guide de gestion s'applique intégralement aux collaborateurs externes et prestataires de services.","Les agents stagiaires bénéficient d'un régime d'exception identique à celui des prestataires.","Les consignes de sécurité des bâtiments ne concernent que les agents sous contrat de droit public."],"a":0,"e":"Le passage opère une distinction claire : les agents publics (titulaires et stagiaires) relèvent du guide, les prestataires relèvent de leur contrat, et les consignes de sécurité s'appliquent indistinctement à tous.","x":["Correct : résume fidèlement le champ d'application interne et l'universalité de la seule sécurité.","En contradiction avec le texte qui restreint les prestataires à leur contrat.","Faux : les stagiaires sont au contraire inclus dans le champ général avec les titulaires.","Faux : le texte précise que la sécurité s'impose à toute personne présente dans les locaux."]},{"id":"verbal-deont-014","f":"single_best","skill":"inference","difficulty":3,"p":"Quelle déduction s'impose logiquement par contraposition ?","s":"Tout fonctionnaire participant à une commission de sélection doit souscrire une déclaration préalable d'absence de conflit d'intérêts. L'agent Marc n'a souscrit aucune déclaration d'absence de conflit d'intérêts.","o":["L'agent Marc ne peut pas régulièrement participer à une commission de sélection.","L'agent Marc est sous le coup d'une procédure disciplinaire pour omission.","L'agent Marc participera à la commission de sélection avec une dispense écrite.","Certains fonctionnaires sont dispensés de déclaration en commission de sélection."],"a":0,"e":"La règle énonce une implication universelle : Participation ⇒ Déclaration. Par contraposition logique (Non Déclaration ⇒ Non Participation), Marc ne peut légalement siéger en commission de sélection.","x":["Correct : contraposition stricte (si participation alors déclaration ; or pas de déclaration donc pas de participation régulière).","Extrapolation injustifiée : le texte n'évoque aucune sanction disciplinaire.","Contredit la règle selon laquelle tout fonctionnaire participant doit déclarer.","Contredit le caractère universel de l'obligation énoncée (« tout fonctionnaire »)."]},{"id":"verbal-cert-015","f":"single_best","skill":"comprehension","difficulty":2,"p":"Quelle affirmation est directement corroborée par les faits mentionnés ?","s":"La nouvelle procédure de délivrance numérique a permis de délivrer 4 500 attestations au premier trimestre, contre 3 000 attestations papier au trimestre correspondant de l'année précédente.","o":["Le volume d'attestations délivrées a augmenté de 1 500 unités entre les deux trimestres comparés.","La procédure numérique a totalement supprimé les erreurs de saisie des agents.","Les usagers préfèrent unanimement le format numérique au format papier.","Toutes les attestations administratives de l'État sont désormais délivrées en ligne."],"a":0,"e":"Seule la hausse factuelle de 1 500 attestations (4 500 contre 3 000) découle directement du texte. Les autres options constituent des jugements subjectifs ou des généralisations sans preuve.","x":["Correct : corroboré par la différence arithmétique directe (4 500 - 3 000 = 1 500).","Extrapolation infondée : le texte ne mentionne aucun taux d'erreur.","Jugement qualitatif subjectif absent des données factuelles du texte.","Généralisation abusive à l'ensemble des attestations administratives de l'État."]}],"numeric":[{"id":"numeric-ratio-001","f":"single_best","skill":"variation","difficulty":2,"p":"Quel service administratif enregistre la plus forte progression relative entre janvier et février ?","s":{"type":"table","caption":"Demandes traitées par service","headers":["Service","Janvier","Février"],"rows":[["A",120,138],["B",80,96],["C",150,165]]},"o":["Service A","Service B","Service C","Service A et Service B à égalité"],"a":1,"e":"Calcul des taux : Service A = (138-120)/120 = +15 % ; Service B = (96-80)/80 = +20 % ; Service C = (165-150)/150 = +10 %. Le service B a la plus forte hausse.","x":["Le service A progresse de (138 - 120) / 120 = +15 %.","Correct : le service B progresse de (96 - 80) / 80 = +20 %, soit la hausse relative la plus forte.","Le service C progresse de (165 - 150) / 150 = +10 %.","Les progressions relatives sont différentes : 15 % pour A et 20 % pour B."]},{"id":"numeric-mean-002","f":"single_best","skill":"moyenne","difficulty":1,"p":"Combien de dossiers sont instruits en moyenne chaque jour ouvré ?","s":"Une équipe instruit 420 dossiers en 7 jours ouvrés à rythme régulier et constant.","o":["50 dossiers","55 dossiers","60 dossiers","65 dossiers"],"a":2,"e":"Le calcul direct de la moyenne quotidienne donne 420 divisé par 7, soit exactement 60 dossiers par jour ouvré.","x":["Sous-estime la cadence quotidienne (50 × 7 = 350 dossiers au lieu de 420).","Erreur de division arithmétique (55 × 7 = 385 dossiers).","Correct : 420 dossiers divisés par 7 jours ouvrés donnent 60 dossiers par jour.","Surestime la cadence quotidienne (65 × 7 = 455 dossiers)."]},{"id":"numeric-perc-003","f":"single_best","skill":"pourcentage","difficulty":1,"p":"Quel est le nouveau temps moyen de réponse après optimisation ?","s":"Un temps moyen de réponse de 40 minutes est réduit de 15 % grâce à une procédure simplifiée.","o":["34 minutes","35 minutes","36 minutes","38 minutes"],"a":0,"e":"La réduction s'élève à 15 % de 40 = 6 minutes. Le nouveau délai est donc de 40 - 6 = 34 minutes.","x":["Correct : réduction de 15 % de 40 min = 6 min ; 40 - 6 = 34 minutes.","Soustraction erronée de 5 minutes au lieu de 6 minutes.","Correspondrait à une réduction de 10 % seulement (4 minutes retranchées).","Correspondrait à une réduction de 5 % seulement (2 minutes retranchées)."]},{"id":"numeric-rate-004","f":"single_best","skill":"pourcentage","difficulty":1,"p":"Combien de demandes reçoivent une décision favorable ?","s":"Sur un total de 250 demandes d'agrément examinées, 72 % sont approuvées.","o":["170 demandes","175 demandes","180 demandes","185 demandes"],"a":2,"e":"Le calcul direct donne 250 × 0,72 = 180 demandes approuvées.","x":["Correspondrait à 68 % de 250 demandes.","Correspondrait à 70 % de 250 demandes.","Correct : 250 × 0,72 = 180 demandes approuvées.","Correspondrait à 74 % de 250 demandes."]},{"id":"numeric-table-005","f":"single_best","skill":"lecture-tableau","difficulty":2,"p":"Quel trimestre présente le taux de résolution le plus performant ?","s":{"type":"table","caption":"Demandes par trimestre","headers":["Trimestre","Reçues","Résolues"],"rows":[["T1",200,160],["T2",240,204],["T3",180,144]]},"o":["Trimestre 1","Trimestre 2","Trimestre 3","Trimestre 1 et Trimestre 3 à égalité"],"a":1,"e":"Taux de résolution : T1 = 160/200 = 80 % ; T2 = 204/240 = 85 % ; T3 = 144/180 = 80 %. Le trimestre 2 est le plus performant.","x":["T1 affiche un taux de 160 / 200 = 80 %.","Correct : T2 affiche un taux de 204 / 240 = 85 %, le plus performant.","T3 affiche un taux de 144 / 180 = 80 %.","T1 et T3 atteignent tous deux 80 %, mais restent inférieurs aux 85 % de T2."]},{"id":"numeric-budget-006","f":"single_best","skill":"pourcentage","difficulty":2,"p":"Quel montant résiduel reste-t-il disponible sur l'enveloppe allouée ?","s":"Une enveloppe budgétaire de 80 000 euros est consommée à hauteur de 45 % au premier trimestre, puis 25 % du budget initial au second trimestre.","o":["24 000 euros","20 000 euros","28 000 euros","16 000 euros"],"a":0,"e":"La consommation totale représente 45 % + 25 % = 70 % du montant initial. La part restante est de 30 % de 80 000 euros, soit 24 000 euros.","x":["Correct : consommation cumulée de 70 % ; reste 30 % de 80 000 € = 24 000 euros.","Correspondrait à 25 % de reliquat (75 % de consommation supposée).","Sous-estimerait la consommation globale à 65 % au lieu de 70 %.","Calculerait seulement 20 % de budget résiduel."]},{"id":"numeric-weight-007","f":"single_best","skill":"moyenne","difficulty":2,"p":"Quelle est la moyenne pondérée des trois évaluations ?","s":"Évaluation A (coefficient 3) : 14/20. Évaluation B (coefficient 2) : 16/20. Évaluation C (coefficient 5) : 11/20.","o":["12,9 / 20","13,2 / 20","13,7 / 20","12,5 / 20"],"a":0,"e":"Calcul de la moyenne pondérée : [(14×3) + (16×2) + (11×5)] / (3+2+5) = (42 + 32 + 55) / 10 = 129 / 10 = 12,9 / 20.","x":["Correct : [(14×3) + (16×2) + (11×5)] / 10 = (42 + 32 + 55) / 10 = 129 / 10 = 12,9.","Erreur d'application sur la pondération du coefficient 5.","Correspondrait à la moyenne simple non pondérée : (14 + 16 + 11) / 3 = 13,67.","Sous-évaluation globale résultant d'une erreur de sommation des coefficients."]},{"id":"numeric-scale-008","f":"single_best","skill":"ratio-proportion","difficulty":2,"p":"Quelle est la distance réelle sur le terrain correspondant à cette mesure ?","s":"Sur un plan d'urbanisme à l'échelle 1:2 500, un tracé de raccordement mesure 8 centimètres.","o":["200 mètres","20 mètres","2 000 mètres","160 mètres"],"a":0,"e":"La distance réelle équivaut à 8 cm × 2 500 = 20 000 cm = 200 mètres.","x":["Correct : 8 cm × 2 500 = 20 000 cm = 200 mètres.","Erreur d'un facteur 10 dans la conversion des centimètres en mètres.","Erreur d'un facteur 10 par excès dans la conversion d'unités.","Confusion dans le calcul (8 × 2 000 au lieu de 8 × 2 500)."]},{"id":"numeric-speed-009","f":"single_best","skill":"operations-simples","difficulty":3,"p":"Combien de temps faut-il pour traiter les 60 dossiers restants en travaillant conjointement ?","s":"L'agent X traite 6 dossiers par heure. L'agent Y traite 4 dossiers par heure.","o":["6 heures","5 heures","7 heures","8 heures"],"a":0,"e":"Leur cadence combinée est de 6 + 4 = 10 dossiers par heure. Pour 60 dossiers, il faut 60 / 10 = 6 heures.","x":["Correct : cadence cumulée de 6 + 4 = 10 dossiers/h ; 60 / 10 = 6 heures.","Sous-estime le temps nécessaire (à 10 dossiers/h, 5 h ne produiraient que 50 dossiers).","Surestimerait la durée nécessaire en minorant le débit conjoint.","Correspondrait au travail d'un seul agent sans mise en commun des cadences."]},{"id":"numeric-delta-010","f":"single_best","skill":"variation","difficulty":2,"p":"De combien de points de pourcentage le taux de présence a-t-il augmenté ?","s":"Le taux de participation des agents aux formations passe de 60 % à 75 % d'une année sur l'autre.","o":["15 points","25 points","15 %","20 points"],"a":0,"e":"La différence entre deux pourcentages s'exprime en points de pourcentage : 75 - 60 = 15 points (alors que la hausse relative est de 25 %).","x":["Correct : l'écart arithmétique absolu entre 75 % et 60 % est de 15 points de pourcentage.","Confond la progression relative (+25 %) avec l'écart absolu en points.","Emploie le symbole % réservé aux variations relatives, et non aux points d'écart.","Erreur arithmétique dans la soustraction 75 - 60."]},{"id":"numeric-table-011","f":"single_best","skill":"lecture-tableau","difficulty":2,"p":"Quel est le montant total des dépenses engagées pour la Direction B sur l'ensemble de l'exercice ?","s":{"type":"table","caption":"Dépenses trimestrielles par direction (en milliers d'euros)","headers":["Direction","Semestre 1","Semestre 2"],"rows":[["Direction A",320,380],["Direction B",240,260],["Direction C",180,220]],"note":"Crédits consommés arrêtés au 31 décembre."},"o":["500 milliers d'euros","480 milliers d'euros","520 milliers d'euros","700 milliers d'euros"],"a":0,"e":"La Direction B a consommé 240 milliers d'euros au premier semestre et 260 milliers d'euros au second semestre. La somme annuelle totale est de 240 + 260 = 500 milliers d'euros (soit 500 000 euros).","x":["Correct : addition des deux semestres de la Direction B : 240 + 260 = 500 milliers d'euros.","Correspondrait à la somme de Direction C (180 + 220 = 400) plus une erreur de calcul.","Erreur d'addition sur le deuxième semestre.","Correspond au total de la Direction A (320 + 380 = 700 milliers d'euros)."]},{"id":"numeric-ratio-012","f":"single_best","skill":"ratio-proportion","difficulty":2,"p":"Quel montant revient au Projet Sud selon la clé de répartition convenue ?","s":"Une dotation régionale de 90 000 euros est partagée entre le Projet Nord et le Projet Sud selon un ratio de 2 pour 3 (2 parts pour Nord, 3 parts pour Sud).","o":["54 000 euros","36 000 euros","45 000 euros","60 000 euros"],"a":0,"e":"Le nombre total de parts est de 2 + 3 = 5 parts. La valeur d'une part s'élève à 90 000 / 5 = 18 000 euros. Le Projet Sud disposant de 3 parts, il reçoit 3 × 18 000 = 54 000 euros.","x":["Correct : 3 parts sur 5 au total : 90 000 × (3 / 5) = 54 000 euros.","Correspond à la part du Projet Nord (2 parts sur 5 : 90 000 × 2 / 5 = 36 000 euros).","Correspondrait à un partage égalitaire 1 pour 1 (90 000 / 2).","Calcul erroné basé sur les deux tiers directs de l'enveloppe globale."]},{"id":"numeric-perc-013","f":"single_best","skill":"pourcentage","difficulty":3,"p":"Quel est le montant final de la subvention après ces deux évolutions successives ?","s":"Une subvention initiale de 50 000 euros augmente de 10 % la première année, puis diminue de 10 % l'année suivante.","o":["49 500 euros","50 000 euros","49 000 euros","51 000 euros"],"a":0,"e":"La première année, la subvention atteint 50 000 × 1,10 = 55 000 euros. La seconde année, la baisse de 10 % s'applique à cette nouvelle base : 55 000 × 0,90 = 49 500 euros (perte nette de 1 % par rapport au montant de départ).","x":["Correct : 50 000 × 1,10 = 55 000 €, puis 55 000 × 0,90 = 49 500 euros.","Erreur classique consistant à croire qu'une hausse de 10 % annule une baisse de 10 %.","Soustraction forfaitaire erronée de 1 000 euros.","Application inversée des pourcentages conduisant à une surévaluation."]},{"id":"numeric-mean-014","f":"single_best","skill":"moyenne","difficulty":2,"p":"Quel est le coût moyen de traitement par dossier sur l'ensemble des dossiers instruits ?","s":"Le bureau 1 traite 100 dossiers pour un coût moyen de 20 euros par dossier. Le bureau 2 traite 300 dossiers pour un coût moyen de 40 euros par dossier.","o":["35 euros","30 euros","32 euros","38 euros"],"a":0,"e":"Le coût total est de (100 × 20 €) + (300 × 40 €) = 2 000 € + 12 000 € = 14 000 €. Le nombre total de dossiers étant de 100 + 300 = 400, le coût moyen pondéré est de 14 000 / 400 = 35 euros.","x":["Correct : coût global = (100 × 20) + (300 × 40) = 2 000 + 12 000 = 14 000 € ; 14 000 / 400 = 35 euros.","Moyenne arithmétique simple erronée sans pondération : (20 + 40) / 2 = 30 euros.","Sous-pondération arbitraire du bureau 2.","Surpondération excessive du bureau 2."]},{"id":"numeric-var-015","f":"single_best","skill":"variation","difficulty":2,"p":"Quel est le pourcentage de variation du nombre de visites entre le premier et le second semestre ?","s":"Le portail administratif enregistre 8 000 visites au premier semestre et 10 000 visites au second semestre.","o":["+25,0 %","+20,0 %","+2 000 %","+15,0 %"],"a":0,"e":"Le taux d'évolution se calcule selon la formule (Valeur finale - Valeur initiale) / Valeur initiale : (10 000 - 8 000) / 8 000 = 2 000 / 8 000 = 0,25, soit une progression de +25,0 %.","x":["Correct : variation relative = (10 000 - 8 000) / 8 000 = 2 000 / 8 000 = +25,0 %.","Erreur de dénominateur : division par la valeur finale 10 000 au lieu de la base 8 000.","Confusion entre la valeur absolue de l'augmentation (+2 000) et le pourcentage.","Sous-estimation arbitraire du ratio de croissance."]}],"planning":[{"id":"planning-slot-001","f":"single_best","skill":"disponibilites","difficulty":2,"p":"Quel créneau permet d'organiser une réunion de 45 minutes commune aux deux participants ?","s":"Léa est disponible de 9 h 00 à 10 h 30 et de 14 h 00 à 15 h 00. Sam est disponible de 9 h 30 à 11 h 00 et de 14 h 30 à 16 h 00.","o":["9 h 00 à 9 h 45","9 h 30 à 10 h 15","14 h 00 à 14 h 45","14 h 30 à 15 h 15"],"a":1,"e":"Le créneau commun le matin s'étend de 9 h 30 à 10 h 30 (durée 60 min). La réunion de 45 minutes peut donc se tenir de 9 h 30 à 10 h 15. Les autres créneaux empiètent sur l'indisponibilité de l'un des participants (Sam avant 9 h 30 le matin ou avant 14 h 30 l'après-midi ; Léa après 15 h 00).","x":["Sam n'est pas disponible avant 9 h 30.","Correct : les deux participants sont disponibles simultanément de 9 h 30 à 10 h 30.","Sam n'est pas disponible avant 14 h 30.","Léa n'est plus disponible après 15 h 00 (la réunion se terminerait à 15 h 15)."]},{"id":"planning-prio-002","f":"single_best","skill":"priorisation","difficulty":2,"p":"Quelle tâche devez-vous impérativement démarrer en premier ?","s":"Il est 9 h 00. Tâche A : échéance 10 h 00, durée 20 min. Tâche B : échéance demain, durée 15 min. Tâche C : échéance aujourd'hui 16 h 00, durée 60 min. Tâche D : échéance 11 h 30, durée 90 min.","o":["Tâche A","Tâche B","Tâche C","Tâche D"],"a":0,"e":"Commencer par A (9 h 00 – 9 h 20) respecte son échéance de 10 h 00 et laisse D se terminer à 10 h 50, avant 11 h 30. Commencer par D ferait manquer l'échéance de A. B et C ont des échéances plus lointaines.","x":["Correct : son échéance (10 h 00) est la plus imminente et impose un démarrage sans attendre.","Échéance fixée au lendemain, donc bien moins urgente que la tâche A.","Échéance fixée à 16 h 00, laissant une marge temporelle suffisante après réalisation de A.","Commencer par D (90 min) mènerait à 10 h 30 : A finirait à 10 h 50, après son échéance de 10 h 00."]},{"id":"planning-order-003","f":"single_best","skill":"dependances","difficulty":1,"p":"Quel ordonnancement respecte l'intégralité des contraintes de préséance imposées ?","s":"L'étape X doit impérativement précéder l'étape Y. L'étape Z doit être réalisée après l'étape Y.","o":["Z, puis X, puis Y","X, puis Z, puis Y","Y, puis X, puis Z","X, puis Y, puis Z"],"a":3,"e":"Les contraintes X < Y et Y < Z imposent strictement l'enchaînement direct X, puis Y, puis Z.","x":["Viole les deux contraintes : Z est placé avant Y, et Y est placé après Z.","Viole la contrainte imposant que Z soit réalisé après Y.","Viole la préséance stricte de X sur Y.","Correct : respecte successivement X avant Y, puis Y avant Z."]},{"id":"planning-room-004","f":"single_best","skill":"conflits","difficulty":2,"p":"Quel créneau faut-il réserver pour satisfaire l'ensemble des contraintes ?","s":"Entretien de 30 minutes avant midi. Salle libre de 10:00 à 10:30 et de 11:00 à 12:00. Candidate indisponible de 10:15 à 11:15.","o":["10:00 à 10:30","10:15 à 10:45","11:00 à 11:30","11:15 à 11:45"],"a":3,"e":"La candidate se libère à 11:15 et la salle est libre jusqu'à 12:00 ; le créneau 11:15-11:45 offre 30 minutes effectives sans conflit.","x":["Conflit avec la candidate dès 10:15, ne laissant que 15 minutes utiles.","La candidate est en indisponibilité sur l'ensemble de cette plage horaire.","La candidate n'est pas encore disponible entre 11:00 et 11:15.","Correct : la salle est libre jusqu'à midi et la candidate est disponible dès 11:15 pour 30 minutes."]},{"id":"planning-delay-005","f":"single_best","skill":"priorisation","difficulty":2,"p":"Quel ordre de traitement minimise le risque de dépassement de délai ?","s":"À 13 h 00 : dossier urgent (durée 45 min, échéance 14 h 00), appel de cadrage (durée 15 min, avant 15 h 00), note de synthèse (durée 90 min, pour le lendemain).","o":["Note de synthèse, appel, dossier urgent","Dossier urgent, appel, note de synthèse","Appel, note de synthèse, dossier urgent","Note de synthèse, dossier urgent, appel"],"a":1,"e":"Le dossier urgent doit se terminer à 13:45 pour respecter l'échéance de 14:00, suivi de l'appel (13:45-14:00), laissant le temps pour la note.","x":["La note de 90 min repousse l'urgence à 14:30, provoquant un dépassement de délai.","Correct : dossier urgent terminé à 13:45 (avant 14:00), appel à 14:00, puis note de synthèse.","Placer la note à 13:15 repousse le dossier urgent à 14:45, après son échéance.","Prioriser la note de 90 min fait manquer l'échéance de 14:00 du dossier urgent."]},{"id":"planning-crit-006","f":"single_best","skill":"dependances","difficulty":3,"p":"Quelle est la durée minimale incompressible pour finaliser ce projet ?","s":"Phase 1 (durée 3 jours). Puis en parallèle : Phase 2A (durée 4 jours) et Phase 2B (durée 6 jours). Enfin Phase 3 (durée 2 jours), démarrant dès que 2A et 2B sont terminées.","o":["11 jours","9 jours","15 jours","13 jours"],"a":0,"e":"Entre 2A et 2B menées en parallèle, le chemin le plus long impose 6 jours. La durée totale incompressible est donc 3 + max(4, 6) + 2 = 3 + 6 + 2 = 11 jours.","x":["Correct : chemin critique déterminé par 3 + max(4, 6) + 2 = 3 + 6 + 2 = 11 jours.","Calcule à tort sur la branche parallèle la plus rapide 2A (3 + 4 + 2 = 9).","Additionne toutes les phases en série sans exploiter la parallélisation (3 + 4 + 6 + 2 = 15).","Surévaluation arbitraire de deux jours par rapport au chemin critique réel."]},{"id":"planning-capa-007","f":"single_best","skill":"agenda-contraintes","difficulty":2,"p":"Combien d'agents supplémentaires faut-il mobiliser pour respecter l'échéance ?","s":"Un chantier d'archivage requiert 120 heures-agent à livrer en 5 jours de 8 heures de travail. L'équipe actuelle compte 2 agents.","o":["1 agent supplémentaire","2 agents supplémentaires","3 agents supplémentaires","4 agents supplémentaires"],"a":0,"e":"En 5 jours, 1 agent produit 5 × 8 = 40 heures. Pour réaliser 120 heures, il faut 120 / 40 = 3 agents au total. Deux étant déjà présents, il faut 1 agent de plus.","x":["Correct : besoin total de 3 agents (120 h / 40 h), 2 étant déjà affectés, 1 agent suffit en renfort.","Confond le nombre d'agents déjà en poste avec le besoin de renfort additionnel.","Indique l'effectif global nécessaire sans soustraire les 2 agents déjà en place.","Surdimensionne l'équipe à 6 agents au total, soit le double de la charge requise."]},{"id":"planning-overlap-008","f":"single_best","skill":"disponibilites","difficulty":2,"p":"Quelle est l'heure d'arrivée la plus tardive possible pour l'agent C, qui reste ensuite jusqu'à 18 h ?","s":"La permanence au guichet doit être assurée sans interruption de 8 h à 18 h. Agent A : 8 h à 12 h. Agent B : 11 h 30 à 15 h 30. L'agent C assure la fin de journée.","o":["15 h 30","16 h 00","12 h 00","17 h 00"],"a":0,"e":"Le guichet est couvert par A puis B jusqu'à 15 h 30. L'agent C doit être présent au plus tard à ce moment ; 12 h fonctionne aussi, mais ce n'est pas l'heure la plus tardive possible.","x":["Correct : l'agent B quittant son poste à 15 h 30, c'est l'heure limite exacte pour éviter une rupture de permanence.","Une arrivée à 16 h 00 entraînerait 30 minutes de fermeture non autorisée du guichet.","Une arrivée à 12 h 00 assure la continuité mais ne constitue pas l'horaire le plus tardif possible.","Une arrivée à 17 h 00 créerait une interruption de service prolongée de 1 h 30."]},{"id":"planning-buffer-009","f":"single_best","skill":"agenda-contraintes","difficulty":2,"p":"De combien de jours ouvrés le projet peut-il au plus être retardé sans dépasser l'échéance ?","s":"L'échéance de livraison tombe dans 20 jours ouvrés. Les tâches restantes du chemin critique totalisent 16 jours ouvrés.","o":["4 jours ouvrés","2 jours ouvrés","6 jours ouvrés","8 jours ouvrés"],"a":0,"e":"Les deux durées sont exprimées dans la même unité (jours ouvrés). La marge totale vaut 20 − 16 = 4 jours ouvrés.","x":["Correct : la marge de battement s'élève exactement à 20 - 16 = 4 jours ouvrés.","Sous-estime de 2 jours la marge réelle disponible.","Surestime la marge de 2 jours, ce qui risquerait d'entraîner un retard effectif.","Surestimation excessive qui provoquerait un dépassement d'échéance certain de 4 jours."]},{"id":"planning-dep-010","f":"single_best","skill":"dependances","difficulty":2,"p":"Sur quelle action pouvez-vous avancer dès ce matin ?","s":"Validation hiérarchique : en attente du rapport financier. Rapport financier : en cours de relecture finale. Envoi des convocations : après la validation. Diffusion du compte rendu : après l'envoi des convocations.","o":["Terminer la relecture du rapport","Obtenir la validation hiérarchique","Envoyer les convocations","Diffuser le compte rendu"],"a":0,"e":"Chaque étape dépend de la précédente : validation, puis convocations, puis compte rendu, et tout attend le rapport financier. Seule sa relecture finale peut avancer dès ce matin.","x":["Correct : c'est la seule tâche immédiatement actionnable dont toutes les dépendances sont levées.","Bloquée tant que le rapport financier n'a pas été finalisé.","Bloquée par la dépendance envers la validation hiérarchique.","Bloquée par les étapes préalables de convocation et de déroulement de la réunion."]},{"id":"planning-trio-011","f":"single_best","skill":"disponibilites","difficulty":2,"p":"Quel créneau horaire permet de tenir un point de synchronisation de 30 minutes commun aux trois agents ?","s":"Agent 1 est disponible de 14 h 00 à 16 h 00. Agent 2 est disponible de 14 h 30 à 17 h 00. Agent 3 est disponible de 13 h 30 à 15 h 30.","o":["14 h 30 à 15 h 00","14 h 00 à 14 h 30","15 h 30 à 16 h 00","16 h 00 à 16 h 30"],"a":0,"e":"La plage commune aux trois agents correspond à l'intersection des créneaux : à partir de 14 h 30 (arrivée de l'Agent 2) et jusqu'à 15 h 30 (départ de l'Agent 3). Le créneau de 14 h 30 à 15 h 00 s'y inscrit parfaitement.","x":["Correct : les trois agents sont simultanément disponibles sur la plage 14 h 30 à 15 h 30.","L'Agent 2 n'est pas encore disponible avant 14 h 30.","L'Agent 3 a terminé sa disponibilité à 15 h 30.","Les Agents 1 et 3 ne sont plus disponibles après 16 h 00."]},{"id":"planning-prio-012","f":"single_best","skill":"priorisation","difficulty":2,"p":"Quelle tâche devez-vous impérativement démarrer dès 14 h 00 pour ne manquer aucune échéance ?","s":"Il est 14 h 00. Tâche 1 : durée 40 min, échéance 15 h 00. Tâche 2 : durée 50 min, échéance 15 h 30. Tâche 3 : durée 30 min, échéance 17 h 00.","o":["Tâche 1","Tâche 2","Tâche 3","Tâche 2 suivie de Tâche 3"],"a":0,"e":"En démarrant par Tâche 1, celle-ci s'achève à 14 h 40 (avant 15 h 00). Tâche 2 peut ensuite s'exécuter de 14 h 40 à 15 h 30, respectant pile son échéance. Si l'on commençait par Tâche 2, Tâche 1 ne finirait qu'à 15 h 30, soit 30 minutes après son échéance.","x":["Correct : commencer par Tâche 1 (14 h 00 à 14 h 40) permet ensuite d'achever Tâche 2 à 15 h 30 avant son terme.","Commencer par Tâche 2 (14 h 00 à 14 h 50) repousserait Tâche 1 à 15 h 30, dépassant son échéance de 15 h 00.","La Tâche 3 a une échéance tardive (17 h 00) et n'est pas prioritaire.","Inverser l'ordre en commençant par Tâche 2 provoque un retard certain sur Tâche 1."]},{"id":"planning-room-013","f":"single_best","skill":"conflits","difficulty":2,"p":"Quel créneau permet de planifier une séance de formation de 45 minutes dans la salle Polyvalente ?","s":"La salle Polyvalente est occupée de 9 h 00 à 10 h 30 et de 11 h 15 à 12 h 30. Le formateur est présent de 10 h 00 à 12 h 00.","o":["10 h 30 à 11 h 15","10 h 00 à 10 h 45","11 h 15 à 12 h 00","11 h 30 à 12 h 15"],"a":0,"e":"La seule fenêtre de disponibilité conjointe de la salle (libre entre 10 h 30 et 11 h 15) et du formateur (présent de 10 h 00 à 12 h 00) est exactement la plage 10 h 30 à 11 h 15, d'une durée de 45 minutes.","x":["Correct : la salle est libre de 10 h 30 à 11 h 15 (45 min) et le formateur y est disponible.","La salle est occupée jusqu'à 10 h 30.","La salle est réservée par une autre réunion à partir de 11 h 15.","Conflit direct d'occupation de la salle qui est prise dès 11 h 15."]},{"id":"planning-chain-014","f":"single_best","skill":"dependances","difficulty":3,"p":"Quelle est la date d'achèvement au plus tôt de l'ensemble des travaux ?","s":"Le projet débute le lundi matin (jour 1). Étape A (3 jours ouvrés). Puis en parallèle, Étape B (2 jours ouvrés) et Étape C (4 jours ouvrés). Étape D (1 jour ouvré) ne démarre que lorsque B et C sont toutes deux achevées. L'équipe ne travaille que les jours ouvrés (du lundi au vendredi).","o":["Jour ouvré 8 (mercredi de la 2e semaine)","Jour ouvré 10 (vendredi de la 2e semaine)","Jour ouvré 6 (lundi de la 2e semaine)","Jour ouvré 7 (mardi de la 2e semaine)"],"a":0,"e":"L'étape A prend les jours 1, 2 et 3. Les étapes B et C se déroulent en parallèle du jour 4 au jour 7 (l'étape critique C imposant 4 jours). L'étape D intervient ensuite sur le jour 8. Le projet s'achève donc au jour ouvré 8.","x":["Correct : chemin critique = Étape A (3 j) + max(Étape B: 2 j, Étape C: 4 j) + Étape D (1 j) = 3 + 4 + 1 = 8 jours ouvrés.","Résultat obtenu en sommant toutes les étapes sans tenir compte du parallélisme de B et C (3 + 2 + 4 + 1 = 10).","Calcul erroné ignorant la durée de l'étape la plus longue en parallèle.","Omet la durée de l'étape finale D."]},{"id":"planning-buffer-015","f":"single_best","skill":"agenda-contraintes","difficulty":2,"p":"À quelle heure au plus tard l'instruction du dossier doit-elle débuter pour respecter l'échéance ?","s":"Un dossier d'agrément requiert 2 h 30 de travail continu. Il doit impérativement être transmis par courriel avant 17 h 00. Une coupure réseau obligatoire et planifiée de 30 minutes a lieu de 15 h 00 à 15 h 30, interdisant toute instruction.","o":["14 h 00","14 h 30","13 h 30","15 h 00"],"a":0,"e":"Le travail effectif demande 2 h 30. Comme la plage d'instruction chevauche nécessairement la coupure réseau de 15 h 00 à 15 h 30 (30 min), le temps global nécessaire est de 2 h 30 + 30 min = 3 h 00. Pour finir à 17 h 00, le travail doit débuter au plus tard à 14 h 00 (14 h 00 – 15 h 00 : 1 h ; 15 h 30 – 17 h 00 : 1 h 30).","x":["Correct : 2 h 30 de travail + 30 min d'interruption = 3 h de temps total requis. 17 h 00 - 3 h = 14 h 00.","Ne prend pas en compte la coupure réseau de 30 minutes, ce qui ferait finir à 17 h 30.","Avance inutilement le démarrage de 30 minutes par rapport à l'heure limite.","Démarrage impossible : la coupure réseau débute précisément à 15 h 00."]}],"situational":[{"id":"situational-serve-001","f":"rating","skill":"servir-client-usager","difficulty":1,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un usager conteste vivement une décision de refus d'allocation, prise conformément au règlement. Vous pouvez en expliquer les motifs, mais vous n'avez pas le pouvoir de la modifier.","o":["Écouter la personne, expliquer les motifs et indiquer les voies de recours et leurs délais.","Expliquer brièvement que la décision est conforme et clore l'échange pour ne pas retarder la file.","Proposer de transmettre le dossier pour réexamen, en laissant entendre qu'une révision reste possible.","Remettre la notice écrite sur les recours et inviter la personne à la lire tranquillement chez elle."],"a":0,"e":"La meilleure réaction combine écoute, explication des motifs et information complète sur les recours, sans promesse. La notice seule informe, mais sans accompagnement ; clore l'échange ou suggérer un réexamen fictif dégrade le service.","r":[4,2,1,3],"x":["Écoute, explique et informe sur les recours : service complet sans fausse promesse.","Exact sur le fond, mais l'usager repart sans comprendre ni connaître ses droits.","Crée une fausse attente : vous n'avez pas le pouvoir de réviser la décision.","Informe correctement, mais sans explication ni écoute."]},{"id":"situational-advise-002","f":"rating","skill":"conseiller","difficulty":1,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un collègue doit répondre aujourd'hui à un usager sur le traitement fiscal d'une subvention et vous demande conseil. Ce sujet ne relève pas de votre expertise. La référente fiscale du service est joignable dans l'heure.","o":["Donner votre meilleure estimation, en précisant qu'elle reste à confirmer par la référente.","Lui dire que ce n'est pas votre domaine et le laisser trouver lui-même le bon interlocuteur.","Reconnaître vos limites et organiser avec lui un échange rapide avec la référente.","Lui transmettre le nom et les coordonnées de la référente fiscale du service."],"a":2,"e":"Conseiller, c'est aussi reconnaître ses limites et orienter efficacement : préparer les faits et organiser le contact avec la référente garantit une réponse fiable dans le délai. Transmettre ses coordonnées aide, mais moins ; une estimation hors expertise risque de circuler comme une réponse.","r":[2,1,4,3],"x":["Une estimation hors de votre domaine risque d'être relayée comme une réponse fiable.","Respecte vos limites, mais n'aide pas votre collègue à tenir le délai.","Reconnaît vos limites et assure une réponse fiable dans le délai.","Oriente correctement, mais sans préparer l'échange ni vérifier le délai."]},{"id":"situational-serve-003","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un usager demande que son dossier soit traité en priorité, en invoquant une connaissance personnelle au sein de votre direction. Le règlement du service ne prévoit aucun traitement prioritaire dans son cas.","o":["Prendre ses coordonnées et lui promettre de l'appeler dès que son dossier aura été traité.","Accepter d'examiner son dossier en premier, puisque cela ne prendra que quelques minutes.","Lui suggérer de contacter directement la personne qu'il cite pour obtenir une dérogation.","Rappeler poliment que les dossiers sont traités dans l'ordre et indiquer le délai prévu."],"a":3,"e":"L'égalité de traitement des usagers interdit tout passe-droit. La réponse la plus pertinente maintient l'ordre de traitement tout en donnant une information utile (le délai). Le rappel promis est acceptable mais n'aborde pas la demande.","r":[3,1,2,4],"x":["Service courtois, mais la demande de priorité n'est pas traitée clairement.","Passe-droit contraire à l'égalité de traitement.","Encourage une démarche de faveur hors procédure.","Maintient l'égalité de traitement et informe sur le délai."]},{"id":"situational-serve-004","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Une personne appelle pour connaître l'état du dossier de son père, actuellement hospitalisé. Elle n'a pas de procuration. Les informations d'un dossier ne peuvent être communiquées qu'à son titulaire ou à une personne mandatée.","o":["Lui donner l'état du dossier, puisque le lien familial paraît évident et la situation urgente.","Refuser de communiquer toute information et mettre poliment fin à l'appel.","Expliquer que vous ne pouvez rien communiquer sans procuration et indiquer comment en obtenir une.","Proposer d'appeler son père à l'hôpital pour faire le point directement avec lui."],"a":2,"e":"La confidentialité s'impose, mais servir l'usager suppose d'expliquer la règle et d'indiquer une solution (la procuration). Contacter le titulaire est possible mais plus lourd ; refuser sans solution respecte la règle sans aider.","r":[1,2,4,3],"x":["Viole la confidentialité du dossier.","Respecte la règle, mais laisse la personne sans solution.","Respecte la règle et donne une solution concrète.","Respecte la confidentialité, mais l'appel à l'hôpital peut être intrusif."]},{"id":"situational-serve-005","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un usager demande une dispense de pièce justificative pour un dossier urgent. Vous n'êtes pas habilité à accorder cette dispense ; votre responsable l'est.","o":["L'inviter à adresser lui-même un courrier à votre responsable, en lui donnant l'adresse.","Préciser que vous n'êtes pas habilité, puis transmettre sa demande écrite au responsable.","Accorder la dispense oralement, la situation vous paraissant de bonne foi.","Lui répondre que la règle ne prévoit aucune exception et clore la demande."],"a":1,"e":"Le respect de la légalité n'empêche pas d'accompagner l'usager : transmettre une demande documentée à l'autorité compétente est la meilleure réponse. Orienter vers un courrier est utile mais plus lent ; décider sans habilitation est exclu.","r":[3,4,1,2],"x":["Oriente vers la bonne personne, mais laisse l'usager faire seul la démarche.","Respecte votre champ de compétence et fait avancer la demande.","Décision prise sans habilitation.","Affirme une règle que vous ne pouvez pas trancher, sans transmettre."]},{"id":"situational-advise-006","f":"rating","skill":"conseiller","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"En réunion de projet, deux directions partenaires défendent deux solutions techniques différentes. Votre responsable vous demande une note pour éclairer sa décision.","o":["Recommander la solution de la direction la plus influente, pour faciliter son adoption.","Comparer les options sur des critères objectifs et formuler une recommandation motivée.","Présenter les deux solutions telles que chaque direction les décrit, sans analyse propre.","Proposer d'abord un atelier commun aux deux directions, puis rédiger l'analyse comparative."],"a":1,"e":"Le rôle de conseil consiste à fournir une analyse neutre, documentée et conclusive. L'atelier peut enrichir l'analyse mais retarde la note ; reprendre les positions sans analyse n'éclaire pas la décision.","r":[1,4,2,3],"x":["Critère d'influence et non de fond : conseil partial.","Analyse objective et recommandation utile au décideur.","Neutre, mais sans valeur ajoutée pour la décision.","Démarche constructive, mais qui retarde la note demandée."]},{"id":"situational-advise-007","f":"rating","skill":"conseiller","difficulty":3,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Votre responsable vous demande de publier dès demain un cahier des charges. Vous y repérez une clause ambiguë qui pourrait provoquer un contentieux lors de l'attribution du marché.","o":["Publier comme demandé et signaler l'ambiguïté une fois la publication effectuée.","Demander l'avis du service juridique avant toute action, quitte à décaler la publication de plusieurs semaines.","Corriger vous-même la clause et publier sans attendre de validation.","Signaler le risque par écrit à votre responsable et proposer une formulation corrigée prête à valider."],"a":3,"e":"Conseiller, c'est alerter sur le risque et proposer une solution qui permet de tenir le délai. Saisir le juridique est prudent mais disproportionné ici ; publier en l'état ou corriger seul contourne la décision du responsable.","r":[2,3,1,4],"x":["Le risque est signalé trop tard pour être évité.","Prudent, mais le retard est disproportionné sans en parler au responsable.","Modification sans validation de la personne qui décide.","Alerte à temps et solution prête : le responsable peut décider vite."]},{"id":"situational-serve-008","f":"rating","skill":"servir-client-usager","difficulty":1,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un usager peu à l'aise avec l'informatique n'arrive pas à faire sa démarche en ligne. Un espace d'aide numérique, avec un agent disponible, se trouve dans le bâtiment.","o":["L'accompagner vers l'espace d'aide numérique pour réaliser la démarche avec lui, étape par étape.","Faire la démarche à sa place en utilisant ses identifiants personnels, pour gagner du temps.","Lui remettre le guide pas à pas et l'inviter à revenir si un problème persiste.","Lui proposer un rendez-vous avec un conseiller numérique dans le courant de la semaine."],"a":0,"e":"L'accompagnement immédiat sur place permet d'aboutir tout en rendant l'usager plus autonome. Un rendez-vous est utile mais diffère la démarche ; utiliser ses identifiants pose un problème de sécurité.","r":[4,1,2,3],"x":["Aide immédiate et adaptée, qui renforce l'autonomie.","Utiliser les identifiants d'autrui pose un problème de sécurité.","Aide minimale pour une personne déjà en difficulté.","Solution valable, mais elle retarde la démarche."]},{"id":"situational-advise-009","f":"rating","skill":"conseiller","difficulty":3,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Votre directrice vous demande quel indicateur retenir dans le rapport annuel pour illustrer la baisse des délais. L'indicateur A, plus favorable, exclut les dossiers incomplets. L'indicateur B couvre tous les dossiers mais montre une baisse plus modeste.","o":["Recommander l'indicateur A, plus favorable, sans détailler son périmètre exact.","Recommander l'indicateur B, sans mentionner l'existence de l'indicateur A.","Présenter les deux indicateurs et leurs limites, puis recommander B en justifiant ce choix.","Recommander l'indicateur A, en précisant son périmètre dans une note de bas de page."],"a":2,"e":"Un bon conseil éclaire complètement la décision : il présente les options, leurs limites et une recommandation motivée. Mentionner le périmètre en note rend A acceptable ; masquer une option ou un périmètre prive la directrice d'informations utiles.","r":[1,2,4,3],"x":["Le périmètre caché peut induire les lecteurs en erreur.","Choix défendable, mais la directrice n'a pas toutes les options.","Transparence complète et recommandation motivée.","Transparent, mais l'information essentielle reste peu visible."]},{"id":"situational-serve-010","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un usager s'énerve car son dossier ne peut pas être enregistré : le système informatique est en panne depuis une heure, pour une durée inconnue.","o":["Lui demander de revenir plus tard, le système étant indisponible pour une durée inconnue.","Lui expliquer que la panne relève du service informatique et que vous n'y pouvez rien.","Lui proposer de faire la démarche en ligne depuis chez lui, une fois le système rétabli.","Reconnaître la gêne, expliquer la panne et proposer de le rappeler dès le rétablissement."],"a":3,"e":"Reconnaître la gêne et garantir un suivi personnalisé apaise la situation et sécurise la démarche. Proposer la démarche en ligne est praticable mais laisse l'usager seul ; renvoyer la responsabilité au service informatique aggrave la tension.","r":[2,1,3,4],"x":["Exact, mais l'usager repart sans solution ni suivi.","Se désolidarise de l'administration et laisse l'usager sans solution.","Solution praticable, mais sans suivi personnalisé ni prise en compte de son énervement.","Reconnaît la gêne, informe et garantit un suivi."]},{"id":"situational-serve-011","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Une personne âgée se présente au guichet, désemparée car elle ne parvient pas à utiliser l'application mobile obligatoire pour renouveler son allocation de chauffage. Le guichet dispose d'un poste informatique d'accompagnement.","o":["L'inviter à s'installer au poste d'accompagnement et l'assister pas à pas pour saisir sa demande en ligne.","Lui indiquer qu'elle doit demander à un proche de faire la démarche sur smartphone à son domicile.","Prendre ses identifiants personnels et compléter intégralement la démarche à sa place pour gagner du temps.","Lui imprimer un formulaire papier non officiel qu'elle remplira sur place et qui sera saisi ultérieurement."],"a":0,"e":"La posture optimale du service public (note 4) consiste à accompagner les usagers vulnérables vers l'autonomie numérique grâce aux moyens dédiés (poste d'accompagnement), sans enfreindre la sécurité des données (ne jamais utiliser les identifiants d'autrui) ni créer de démarches parallèles non réglementaires.","r":[4,2,1,2],"x":["Très approprié (4) : inclusion numérique bienveillante favorisant l'autonomie de l'usager dans un cadre sécurisé.","Inapproprié (2) : renvoi vers des tiers sans solution interne alors qu'un accompagnement sur place est possible.","Très inapproprié (1) : manipulation des identifiants personnels d'un usager enfreignant les règles de sécurité.","Inapproprié (2) : utilisation d'une procédure non homologuée risquant d'invalider la demande de l'usager."]},{"id":"situational-advise-012","f":"rating","skill":"conseiller","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un jeune collègue chargé d'études doit animer une réunion avec des représentants syndicaux sur un projet de refonte des horaires. Il craint des tensions et vous demande comment structurer son intervention.","o":["Lui conseiller de présenter d'abord les constats factuels et objectifs, puis d'ouvrir un échange structuré sur les besoins exprimés.","Lui recommander d'imposer fermement le calendrier ministériel dès le début pour couper court à toute discussion.","Lui suggérer d'annuler la réunion et de communiquer la décision unilatéralement par note de service écrite.","Lui proposer de faire une intervention informelle sans ordre du jour pour éviter de formaliser les désaccords."],"a":0,"e":"Le conseil professionnel (note 4) encourage une méthode rigoureuse : baser l'échange sur des éléments factuels partagés, donner la parole de manière cadrée et écouter les observations pour coconstruire la mise en œuvre.","r":[4,1,1,2],"x":["Très approprié (4) : démarche constructive et objective favorisant le dialogue social tout en gardant un cadre professionnel.","Très inapproprié (1) : posture autoritaire qui envenime le conflit et rompt la confiance avec les partenaires sociaux.","Très inapproprié (1) : déni de concertation contraire aux principes d'administration moderne et participative.","Inapproprié (2) : absence de cadre qui décrédibilise l'administration et risque de rendre les échanges stériles."]},{"id":"situational-serve-013","f":"rating","skill":"servir-client-usager","difficulty":2,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un journaliste demande par téléphone la communication immédiate du projet de rapport d'audit interne sur la gestion d'un établissement public, document non encore validé par la commission de tutelle.","o":["Lui expliquer courtoisement que le rapport est un document préparatoire non communicable et l'orienter vers le service de presse ministériel.","Lui envoyer immédiatement une copie par courriel sous couvert d'anonymat pour favoriser la transparence publique.","Refuser sèchement de lui répondre et raccrocher sans lui donner la moindre explication.","Lui promettre une transmission exclusive dès le lendemain sans en référer à votre hiérarchie."],"a":0,"e":"Les documents préparatoires ne sont pas communicables tant que la décision définitive n'est pas adoptée. L'attitude correcte (note 4) consiste à faire preuve de pédagogie sur l'état juridique du document et à réorienter vers le service officiel habilité.","r":[4,1,1,2],"x":["Très approprié (4) : respect du secret professionnel et des règles de communicabilité des actes préparatoires avec orientation adaptée.","Très inapproprié (1) : fuite délibérée d'un document non officiel constituant une faute professionnelle grave.","Très inapproprié (1) : incivilité et manquement au devoir élémentaire de courtoisie du fonctionnaire.","Inapproprié (2) : promesse illégale et violation des prérogatives de la hiérarchie et du service de communication."]},{"id":"situational-advise-014","f":"rating","skill":"conseiller","difficulty":3,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Votre chef de service souhaite accélérer l'octroi d'un marché public avant la fin de l'exercice budgétaire pour éviter la perte de crédits, en omettant l'avis obligatoire de la commission des marchés.","o":["Alerter le chef de service par écrit sur le risque d'illégalité et de nullité du marché, et proposer un calendrier de passation accéléré mais légal.","Valider la procédure sans réserve pour obéir aux instructions hiérarchiques et préserver les crédits budgétaires.","Dénoncer immédiatement votre supérieur hiérarchique au parquet sans lui faire part au préalable de l'irrégularité.","Refuser d'exécuter la tâche oralement en menaçant de vous mettre en grève."],"a":0,"e":"L'agent public de catégorie A1 a un devoir de conseil technique : il doit formuler par écrit une mise en garde loyale sur les risques juridiques (nullité du marché, engagement de responsabilité) tout en étant force de proposition pour rechercher une issue légale dans les délais.","r":[4,1,1,2],"x":["Très approprié (4) : devoir de conseil vigilant protégeant l'administration contre l'illégalité tout en proposant une solution constructive.","Très inapproprié (1) : complicité d'une irrégularité juridique majeure contraire au devoir de probité.","Très inapproprié (1) : rupture disproportionnée de la voie hiérarchique sans démarche préalable de clarification interne.","Inapproprié (2) : réaction émotionnelle conflictuelle non conforme à la déontologie administrative."]},{"id":"situational-serve-015","f":"rating","skill":"servir-client-usager","difficulty":1,"p":"Évaluez la pertinence de chaque réaction dans ce contexte.","s":"Un usager affirme avec véhémence au guichet qu'il a déposé une pièce justificative essentielle il y a trois jours, mais celle-ci n'apparaît nulle part dans son dossier informatique.","o":["Vérifier le bac des courriers en cours de numérisation et l'aider à réimprimer la pièce si possible.","Lui soutenir qu'il se trompe et refuser formellement tout examen de son dossier sans la pièce originale.","Valider immédiatement sa demande sans la pièce requise pour désamorcer son mécontentement au guichet.","L'orienter vers le commissariat de police pour signaler la perte de sa pièce justificative déposée."],"a":0,"e":"Face à un litige de transmission, l'agent doit faire preuve d'empathie sans présumer de la faute de l'usager, vérifier les points d'attente internes (numérisation) et lui faciliter la fourniture immédiate d'une copie de substitution pour débloquer son dossier.","r":[4,2,1,2],"x":["Très approprié (4) : posture de recherche active de solution sans accusation mutuelle, conciliant bienveillance et rigueur.","Inapproprié (2) : mise en cause agressive de la bonne foi de l'usager bloquant la relation de service.","Très inapproprié (1) : dispense de justificatif légal sans fondement exposant le service à une décision illégale.","Inapproprié (2) : démarche absurde et disproportionnée qui ne règle pas le problème de dossier."]}]};
/* QUESTION_BANK_END */
const state={route:"accueil",dark:false,session:null,answered:0,points:0,sessionCount:5},$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],names={accueil:"Vue d'ensemble",entrainement:"Entraînement",session:"Session",results:"Résultats",simulation:"Simulation",ressources:"Ressources",methode:"Méthode"};

/* All item text is escaped: question content is data, never markup. */
function esc(v){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function shuffle(a){const r=[...a];for(let i=r.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]]}return r}
function skillOf(x){return x.skill?` · ${esc(skillLabels[x.skill]||x.skill)}`:""}
function stimulusHtml(s){
  if(s==null)return"";
  if(typeof s==="string")return`<div class="stimulus text">${esc(s)}</div>`;
  if(s.type==="shapes")return`<div class="stimulus"><div class="shapes" role="img" aria-label="Série de figures">${esc(s.text)}</div></div>`;
  if(s.type==="table"){
    const head=`<tr>${s.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join("")}</tr>`;
    const body=s.rows.map(r=>`<tr>${r.map((c,i)=>i===0?`<th scope="row">${esc(c)}</th>`:`<td>${esc(typeof c==="number"?c.toLocaleString("fr-FR"):c)}</td>`).join("")}</tr>`).join("");
    return`<div class="stimulus"><table class="data">${s.caption?`<caption>${esc(s.caption)}</caption>`:""}<thead>${head}</thead><tbody>${body}</tbody></table>${s.note?`<p class="note">${esc(s.note)}</p>`:""}</div>`;
  }
  return"";
}
/* Options are shuffled once per question so the answer position carries no information. */
function prepare(x,m){const order=x.f==="tfcs"?x.o.map((_,i)=>i):shuffle(x.o.map((_,i)=>i));return{...x,m,o:order.map(i=>x.o[i]),r:x.r?order.map(i=>x.r[i]):null,x:x.x?order.map(i=>x.x[i]):null,a:order.indexOf(x.a)}}
function scoreRating(user,key){const gap=key.reduce((s,k,i)=>s+Math.abs(k-user[i]),0)/key.length;return Math.max(0,1-gap/3)}

function route(n){if(state.session&&!state.session.done&&!["session","results"].includes(n)){if(!confirm("Quitter cette session ?"))return;clearInterval(state.session.interval);state.session=null}state.route=n;$$('.view').forEach(v=>v.classList.toggle('active',v.id===`v-${n}`));$$('[data-route]').forEach(b=>b.setAttribute('aria-current',b.dataset.route===n?'page':'false'));$('#crumb').textContent=names[n];history.replaceState(null,"",n==='accueil'?location.pathname:`#${n}`);scrollTo({top:0,behavior:'smooth'});if(n==='accueil')dashboard()}

function optionReview(t){
  const x=t.x,ans=t.ans;
  if(x.f==="rating"){
    return x.o.map((opt,i)=>{const u=ans&&ans.choice?ans.choice[i]:null,k=x.r[i],cls=u==null?"":Math.abs(u-k)<=0?" is-user-correct":Math.abs(u-k)===1?"":" is-user-wrong";
      return`<div class="review-opt${cls}${i===x.a?" is-target":""}"><span>${esc(opt)}${x.x?`<small class="why">${esc(x.x[i])}</small>`:""}</span><span class="review-tag ${u===k?"user correct":"target"}">Vous : ${u??"—"} · Réf. : ${k}</span></div>`}).join("");
  }
  return x.o.map((opt,i)=>{const isUser=ans&&ans.choice===i,isTarget=i===x.a;let cls="review-opt",tag="";
    if(isUser&&isTarget){cls+=" is-user-correct";tag='<span class="review-tag user correct">Votre choix (correct)</span>'}
    else if(isUser){cls+=" is-user-wrong";tag='<span class="review-tag user">Votre choix</span>'}
    else if(isTarget){cls+=" is-target";tag='<span class="review-tag target">Bonne réponse</span>'}
    return`<div class="${cls}"><span>${esc(opt)}${x.x?`<small class="why">${esc(x.x[i])}</small>`:""}</span>${tag}</div>`}).join("");
}
function renderReview(filter="all"){
  const s=state.session;if(!s)return;
  const items=s.questions.map((x,i)=>{const ans=s.answers[i];return{x,i,ans,isGood:Boolean(ans&&ans.good),isSkip:!ans||ans.choice===null}});
  const okCount=items.filter(t=>t.isGood).length;
  $('#review-filters').innerHTML=`<button type="button" data-filter="all" aria-pressed="${filter==='all'}">Toutes (${items.length})</button><button type="button" data-filter="ko" aria-pressed="${filter==='ko'}">À revoir (${items.length-okCount})</button><button type="button" data-filter="ok" aria-pressed="${filter==='ok'}">Réussies (${okCount})</button>`;
  $('#review-filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(b)renderReview(b.dataset.filter)};
  const filtered=items.filter(t=>filter==='ok'?t.isGood:filter==='ko'?!t.isGood:true);
  if(!filtered.length){$('#review').innerHTML='<p class="lede" style="padding:var(--s4);text-align:center">Aucun élément dans cette catégorie.</p>';return}
  $('#review').innerHTML=filtered.map(t=>{const st=t.isGood?['is-good','ok','Correct']:t.isSkip?['is-skip','skipped','Passée']:['is-bad','ko','À revoir'];
    const pts=t.x.f==="rating"&&t.ans&&t.ans.choice?` · ${Math.round(t.ans.points*100)} %`:"";
    return`<details class="review-item ${st[0]}" ${filter==='ko'?'open':''}><summary class="review-summary"><div class="review-summary-left"><strong>#${t.i+1}</strong><span>${esc(modules[t.x.m].title)}${skillOf(t.x)}</span></div><span class="review-badge ${st[1]}">${st[2]}${pts}</span></summary><div class="review-detail"><h3 class="qprompt">${esc(t.x.p)}</h3>${stimulusHtml(t.x.s)}<div class="review-options">${optionReview(t)}</div><div class="feedback ${t.isGood?'good':'bad'}"><strong>Explication pédagogique</strong><p>${esc(t.x.e)}</p></div></div></details>`}).join('');
}

function start(type,countChoice){
  let questions,title,seconds,guided=true;
  const pick=(k,n)=>shuffle(q[k]||[]).slice(0,n).map(x=>prepare(x,k));
  const count=countChoice!==undefined?countChoice:state.sessionCount;
  if(type==='diagnostic'){questions=shuffle(Object.keys(modules).flatMap(k=>pick(k,2)));title='Diagnostic transversal';seconds=900}
  else if(type==='simulation'){questions=shuffle(Object.keys(modules).flatMap(k=>pick(k,3)));title='Simulation A1';seconds=1500;guided=false}
  else if(type==='examen'){return startExam()}
  else{
    const total=(q[type]||[]).length;
    const n=(count==='all'||Number(count)>=total)?total:(Number(count)||5);
    questions=pick(type,n);
    title=`${modules[type].title} · ${questions.length} questions`;
    const baseMins=modules[type].minutes||10;
    seconds=Math.max(180,Math.round(questions.length*(baseMins*60/(total||10))));
  }
  if(!questions.length)return;
  state.session={type,countChoice:count,questions,title,seconds,guided,index:0,answers:[],locked:false,done:false};
  $('#sessiontitle').textContent=title;$('#sessionkind').textContent=guided?'Entraînement guidé avec retour immédiat':'Simulation chronométrée (correction à la fin)';
  route('session');render();tick();
  state.session.interval=setInterval(()=>{state.session.seconds--;tick();if(state.session.seconds<=0)finish()},1000);
}
function startExam(){
  const sections=[],questions=[];
  for(const k of EXAM.sections){const qs=shuffle(q[k]||[]).slice(0,EXAM.questionsPerSection||Infinity).map(x=>prepare(x,k));if(!qs.length)continue;sections.push({cat:k,from:questions.length,to:questions.length+qs.length-1});questions.push(...qs)}
  if(!questions.length)return;
  state.session={type:'examen',questions,title:'Examen blanc A1 · 2 h',seconds:EXAM.minutesPerSection*60,guided:false,index:0,answers:[],locked:false,done:false,exam:{sections,current:0,waiting:true}};
  $('#sessiontitle').textContent=state.session.title;$('#sessionkind').textContent='Examen blanc : tests successifs chronométrés, correction à la fin';
  route('session');tick();sectionIntro();
}
function sectionIntro(){
  const s=state.session,e=s.exam,sec=e.sections[e.current],n=sec.to-sec.from+1;
  e.waiting=true;s.seconds=EXAM.minutesPerSection*60;tick();
  $('#position').textContent=`Test ${e.current+1} / ${e.sections.length}`;
  $('#sessionbar').style.setProperty('--value',`${(sec.from/s.questions.length)*100}%`);
  $('#question').innerHTML=`<p class="eyebrow">Test ${e.current+1} sur ${e.sections.length}</p><h2 class="qprompt">${esc(modules[sec.cat].title)}</h2><p class="lede">${n} questions · ${EXAM.minutesPerSection} minutes. Le chronomètre démarre quand vous commencez ; à la fin du temps, le test suivant s'ouvre et les questions non traitées comptent comme non répondues.</p><p class="lede">Le jour de l'épreuve, lisez les consignes et résolvez les exemples proposés au début de chaque test.</p><div class="actions"><button class="btn" id="startsection">Commencer le test</button></div>`;
  $('#startsection').onclick=()=>{e.waiting=false;s.index=sec.from;render();s.interval=setInterval(()=>{s.seconds--;tick();if(s.seconds<=0)endSection()},1000)};
}
function endSection(){
  const s=state.session;if(!s||!s.exam||s.done)return;
  clearInterval(s.interval);
  const e=s.exam,sec=e.sections[e.current];
  for(let i=sec.from;i<=sec.to;i++)if(!s.answers[i])s.answers[i]={choice:null,good:false,points:0};
  e.current++;
  if(e.current>=e.sections.length)return finish();
  s.index=e.sections[e.current].from;sectionIntro();
}
function tick(){const x=Math.max(0,state.session.seconds);$('#timer').textContent=`${String(Math.floor(x/60)).padStart(2,'0')}:${String(x%60).padStart(2,'0')}`;$('#timer').classList.toggle('low',x<60)}
function render(){
  const s=state.session,x=s.questions[s.index];s.locked=false;
  const sec=s.exam?s.exam.sections[s.exam.current]:null;
  $('#position').textContent=sec?`Test ${s.exam.current+1}/${s.exam.sections.length} · ${s.index-sec.from+1} / ${sec.to-sec.from+1}`:`${s.index+1} / ${s.questions.length}`;
  $('#sessionbar').style.setProperty('--value',`${(s.index/s.questions.length)*100}%`);
  let body;
  if(x.f==="rating"){
    body=`<p class="rating-help">Notez chaque réaction de 1 (très inapproprié) à 4 (très approprié).</p><div class="ratings">${x.o.map((z,i)=>`<fieldset class="rating-row" data-row="${i}"><legend>${esc(z)}</legend><div class="scale">${ratingLabels.map((l,v)=>`<label title="${l}"><input type="radio" name="r${i}" value="${v+1}"><span>${v+1}</span><small>${l}</small></label>`).join("")}</div><div class="rowfeedback"></div></fieldset>`).join("")}</div>`;
  }else{
    body=`<fieldset class="options${x.m==="abstract"?" figs":""}"><legend class="sr">Options de réponse</legend>${x.o.map((z,i)=>`<label class="option"><input type="radio" name="answer" value="${i}"><span>${esc(z)}</span></label>`).join('')}</fieldset>`;
  }
  $('#question').innerHTML=`<p class="eyebrow">${esc(modules[x.m].title)}${skillOf(x)}</p><h2 class="qprompt">${esc(x.p)}</h2>${stimulusHtml(x.s)}${body}<div id="feedback" role="status" aria-live="polite"></div><div class="actions"><button class="btn" id="validate">${s.guided?'Valider':'Réponse suivante'}</button><button class="btn ghost" id="pass">Passer</button>${sec?'<button class="btn secondary" id="endsection">Terminer ce test</button>':''}</div>`;
  $('#validate').onclick=submit;$('#pass').onclick=()=>record(null);
  if(sec)$('#endsection').onclick=()=>{if(confirm('Terminer ce test ? Les questions non traitées compteront comme non répondues.'))endSection()};
}
function submit(){
  const x=state.session.questions[state.session.index];
  if(x.f==="rating"){
    const vals=x.o.map((_,i)=>{const c=$(`input[name=r${i}]:checked`);return c?Number(c.value):null});
    if(vals.includes(null)){$('#feedback').innerHTML='<div class="feedback bad"><strong>Notation incomplète</strong>Notez chacune des réactions, ou passez la question.</div>';return}
    return record(vals);
  }
  const c=$('input[name=answer]:checked');
  if(!c){$('#feedback').innerHTML='<div class="feedback bad"><strong>Sélection requise</strong>Choisissez une option ou passez.</div>';return}
  record(Number(c.value));
}
function record(choice){
  const s=state.session;if(s.locked)return;s.locked=true;
  const x=s.questions[s.index];
  const points=choice===null?0:x.f==="rating"?scoreRating(choice,x.r):choice===x.a?1:0;
  const good=x.f==="rating"?points>=0.75:points===1;
  s.answers[s.index]={choice,good,points};
  if(choice!==null){state.answered++;state.points+=points}
  if(!s.guided||choice===null)return next();
  if(x.f==="rating"){
    $$('.rating-row').forEach((row,i)=>{row.querySelectorAll('input').forEach(inp=>inp.disabled=true);const u=choice[i],k=x.r[i];row.classList.add(u===k?'correct':Math.abs(u-k)===1?'near':'wrong');row.querySelector('.rowfeedback').textContent=`Votre note : ${u} · note de référence : ${k}${x.x?` — ${x.x[i]}`:""}`});
    $('#feedback').innerHTML=`<div class="feedback ${good?'good':'bad'}"><strong>${Math.round(points*100)} % de concordance</strong>${esc(x.e)}</div>`;
  }else{
    $$('.option').forEach((el,i)=>{if(i===x.a)el.classList.add('correct');if(i===choice&&choice!==x.a)el.classList.add('wrong');el.querySelector('input').disabled=true});
    $('#feedback').innerHTML=`<div class="feedback ${good?'good':'bad'}"><strong>${good?'Bonne réponse':'À revoir'}</strong>${esc(x.e)}${x.x&&choice!==x.a?`<p class="why">Votre choix : ${esc(x.x[choice])}</p>`:""}</div>`;
  }
  $('#validate').textContent=s.index===s.questions.length-1?'Voir le bilan':'Question suivante';$('#validate').onclick=next;$('#pass').disabled=true;
}
function next(){const s=state.session;if(s.exam&&s.index>=s.exam.sections[s.exam.current].to)return endSection();if(s.index<s.questions.length-1){s.index++;render()}else finish()}
function finish(){
  const s=state.session;if(!s||s.done)return;s.done=true;clearInterval(s.interval);
  const total=s.questions.length,pts=s.answers.reduce((n,a)=>n+(a?a.points:0),0),good=s.answers.filter(a=>a&&a.good).length,pct=Math.round(pts/total*100);
  $('#ring').style.setProperty('--score',`${pct}%`);$('#score').textContent=`${pct}%`;
  $('#message').textContent=pct>=80?'Très bonne maîtrise':pct>=60?'Base solide à consolider':'Analysez vos erreurs';
  $('#detail').textContent=`${good} question(s) réussie(s) sur ${total}. Les questions de jugement situationnel comptent selon la concordance de vos notes. Ce pourcentage n’est pas une note Stanine.`;
  if(s.exam){
    const rows=s.exam.sections.map(sec=>{const idx=[];for(let i=sec.from;i<=sec.to;i++)idx.push(i);const p=idx.reduce((n,i)=>n+(s.answers[i]?s.answers[i].points:0),0),done=idx.filter(i=>s.answers[i]&&s.answers[i].choice!==null).length;return{cat:sec.cat,pct:Math.round(p/idx.length*100),done,n:idx.length}});
    const avg=Math.round(rows.reduce((n,r)=>n+r.pct,0)/rows.length);
    $('#ring').style.setProperty('--score',`${avg}%`);$('#score').textContent=`${avg}%`;
    $('#message').textContent=avg>=80?'Très bonne maîtrise':avg>=60?'Base solide à consolider':'Analysez vos erreurs';
    $('#detail').innerHTML=`Moyenne des ${rows.length} tests (chacun compte autant, comme dans la notation officielle) : <strong>${avg} %</strong>. Ce n'est pas une note Stanine.<span class="sectionscores">${rows.map(r=>`<span class="row"><span>${esc(modules[r.cat].title)}</span><span>${r.pct} % · ${r.done}/${r.n} traitées</span></span>`).join('')}</span>`;
  }
  renderReview('all');$('#retry').onclick=()=>start(s.type,s.countChoice);route('results');
}
function dashboard(){const pct=state.answered?Math.round(state.points/state.answered*100):null;$('#accuracy').textContent=pct===null?'—':`${pct}%`;$('#homebar').style.setProperty('--value',`${pct||0}%`);$('#summary').textContent=state.answered?`${state.answered} question(s) répondue(s), questions passées non comptées.`:'Commencez un module pour établir votre diagnostic.'}
function theme(){document.documentElement.dataset.theme=state.dark?'dark':'light';$('#theme').innerHTML=state.dark?sun:moon;$('#theme').setAttribute('aria-label',`Passer au mode ${state.dark?'clair':'sombre'}`)}
function renderModules(){
  const cnt=state.sessionCount;
  $('#modules').innerHTML=Object.entries(modules).map(([k,m])=>{
    const total=(q[k]||[]).length;
    const drawText=cnt==='all'||Number(cnt)>=total?`${total} questions`:`${cnt} sur ${total} (tirage aléatoire)`;
    return `<button class="module" data-module="${k}"><span class="code">${m.code}</span><span class="count">${drawText}</span><h3>${esc(m.title)}</h3><p>${esc(m.desc)}</p></button>`;
  }).join('');
}
function init(){
  renderModules();
  $('#modules').onclick=e=>{const b=e.target.closest('[data-module]');if(b)start(b.dataset.module)};
  const picker=$('#session-picker');
  if(picker){
    picker.onclick=e=>{
      const chip=e.target.closest('.chip');
      if(!chip)return;
      state.sessionCount=chip.dataset.size==='all'?'all':Number(chip.dataset.size);
      $$('#session-picker .chip').forEach(c=>c.setAttribute('aria-pressed',c===chip?'true':'false'));
      renderModules();
    };
  }
  $$('[data-route]').forEach(b=>b.onclick=e=>{e.preventDefault();route(b.dataset.route)});
  $$('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));
  state.dark=matchMedia('(prefers-color-scheme:dark)').matches;theme();$('#theme').onclick=()=>{state.dark=!state.dark;theme()};
  const first=location.hash.slice(1);route(['entrainement','simulation','ressources','methode'].includes(first)?first:'accueil');
}
init();
